using System;
using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class UnitsDiceActivation : MonoBehaviour
{
	[Header("Attack animation")]
	[SerializeField]
	protected float attackAnimationDuration;

	[SerializeField]
	private AnimationCurve attackAnimationCurve;

	[SerializeField]
	private float attackingAnimationMovementAmount;

	[Header("Data")]
	[SerializeField]
	private ActionInstanceData actionInstanceData;

	[Header("Components")]
	[SerializeField]
	private GameObject diceInstance3DPrefab;

	[SerializeField]
	private DiceOwnerEnum diceOwnerEnum;

	[SerializeField]
	private UnitEffects unitEffects;

	[SerializeField]
	private FloatReference diceRollingZPosition;

	[SerializeField]
	private SpriteControl spriteControl;

	[Header("Positions")]
	[SerializeField]
	private Transform oneDiceSpawnTransform;

	[SerializeField]
	private Transform basicDiceSpawnTransform;

	[SerializeField]
	private Transform boostDiceSpawnTransform;

	private float perspectiveToOrthographicCameraAmount = 1.034f;

	[Header("Runtime")]
	[SerializeField]
	protected Dice defaultDice;

	[SerializeField]
	protected Dice basicDice;

	[SerializeField]
	protected Dice boostDice;

	[SerializeField]
	protected DiceInstance basicDiceInstance;

	[SerializeField]
	protected DiceInstance boostDiceInstance;

	[ShowNonSerializedField]
	protected bool boosted;

	protected bool hideDiceFace;

	private List<ActionValueModifier> actionValueModifiers = new List<ActionValueModifier>();

	public bool BasicDiceSpawned;

	public bool BoostDiceSpawned;

	private Vector3 idlePosition;

	private Vector3 oneDiceSpawnPosition => oneDiceSpawnTransform.position.ZeroZ() / perspectiveToOrthographicCameraAmount + GetDiceHeightAdjustment();

	private Vector3 basicDiceSpawnPosition => basicDiceSpawnTransform.position.ZeroZ() / perspectiveToOrthographicCameraAmount + GetDiceHeightAdjustment();

	private Vector3 boostDiceSpawnPosition => boostDiceSpawnTransform.position.ZeroZ() / perspectiveToOrthographicCameraAmount + GetDiceHeightAdjustment();

	public DiceInstance BasicDiceInstance => basicDiceInstance;

	public DiceInstance BoostDiceInstance => boostDiceInstance;

	public bool IsBoosted => boosted;

	public List<ActionValueModifier> ActionValueModifiers => actionValueModifiers;

	private Transform skeletonTransform => spriteControl.SkeletonTransform;

	protected virtual Vector3 GetDiceHeightAdjustment()
	{
		return Vector3.zero;
	}

	public void TurnOnBoosted()
	{
		boosted = true;
	}

	public virtual void Initialize(Dice defaultDice)
	{
		StoreDice();
		InitializeWithoutStoreDice(defaultDice);
	}

	public void InitializeWithoutStoreDice(Dice defaultDice, bool tryStoreBoostedDice = false)
	{
		idlePosition = Vector3.one * 100000f;
		actionValueModifiers.Clear();
		hideDiceFace = false;
		if (tryStoreBoostedDice)
		{
			StoreBoostDice();
			if (BasicDiceSpawned)
			{
				basicDiceInstance.SetOriginalPosition(oneDiceSpawnPosition + Vector3.right * 0.2f);
			}
		}
		boosted = false;
		this.defaultDice = defaultDice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
		basicDice = defaultDice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
		boostDice = defaultDice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
	}

	public void InitializeWithoutStoreDiceWithoutResettingEmpowerAndHideDiceface(Dice defaultDice)
	{
		this.defaultDice = defaultDice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
		basicDice = defaultDice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
		boostDice = defaultDice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
	}

	public void UpdateDiceInstances()
	{
		basicDiceInstance.UpdateDice(basicDice);
		basicDiceInstance.UpdateDiceFace(updateOutline: false);
		if (boosted)
		{
			boostDiceInstance.UpdateDice(boostDice);
			boostDiceInstance.UpdateDiceFace(updateOutline: false);
		}
	}

	public virtual int GetDiceAmount()
	{
		if (!boosted)
		{
			return 1;
		}
		return 2;
	}

	public virtual List<DiceInstance> GetDiceInstancesToRoll(bool ignoreDisabledActions = false)
	{
		List<DiceInstance> list = new List<DiceInstance>();
		if (basicDiceInstance != null)
		{
			if (ignoreDisabledActions)
			{
				if (basicDiceInstance.ActionEnabled)
				{
					list.Add(basicDiceInstance);
				}
			}
			else
			{
				list.Add(basicDiceInstance);
			}
		}
		if (boosted && boostDiceInstance != null)
		{
			if (ignoreDisabledActions)
			{
				if (boostDiceInstance.ActionEnabled)
				{
					list.Add(boostDiceInstance);
				}
			}
			else
			{
				list.Add(boostDiceInstance);
			}
		}
		return list;
	}

	public virtual void Spawn3DDice()
	{
		CheckDisoriented();
		if (!BasicDiceSpawned)
		{
			Vector3 position = oneDiceSpawnPosition;
			if (boosted)
			{
				position = basicDiceSpawnPosition;
				SpawnDice(out boostDiceInstance, out BoostDiceSpawned, boostDiceSpawnPosition);
				InitializeDice(boostDiceInstance, boostDice, boostDiceSpawnPosition);
			}
			SpawnDice(out basicDiceInstance, out BasicDiceSpawned, position);
			InitializeDice(basicDiceInstance, basicDice, position);
			return;
		}
		Vector3 vector = oneDiceSpawnPosition;
		if (boosted)
		{
			vector = basicDiceSpawnPosition;
			if (!BoostDiceSpawned)
			{
				SpawnDice(out boostDiceInstance, out BoostDiceSpawned, boostDiceSpawnPosition);
				InitializeDice(boostDiceInstance, boostDice, boostDiceSpawnPosition);
			}
			else
			{
				UpdateDiceAndSetupToRoll(boostDiceInstance, boostDice);
			}
			basicDiceInstance.SetNewPosition(vector);
			UpdateDiceAndSetupToRoll(basicDiceInstance, basicDice);
		}
		else
		{
			UpdateDiceAndSetupToRoll(basicDiceInstance, basicDice);
		}
	}

	private void CheckDisoriented()
	{
		if (unitEffects.IsDisoriented())
		{
			basicDice = unitEffects.RandomizeValue(basicDice);
			if (boosted)
			{
				boostDice = unitEffects.RandomizeValue(boostDice);
			}
		}
	}

	private void SpawnDice(out DiceInstance diceInstance, out bool diceSpawned, Vector3 position)
	{
		GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(diceInstance3DPrefab.name, position + Vector3.forward * diceRollingZPosition.Value);
		diceInstance = @object.GetComponent<DiceInstance>();
		diceSpawned = true;
	}

	private void InitializeDice(DiceInstance diceInstance, Dice dice, Vector3 position)
	{
		diceInstance.Initialize(dice, actionInstanceData, base.gameObject, diceOwnerEnum, hideDiceFace);
		diceInstance.SetOriginalPosition(position);
		diceInstance.SetupDiceToRoll();
	}

	private void UpdateDiceAndSetupToRoll(DiceInstance diceInstance, Dice dice)
	{
		diceInstance.SetupDiceToRoll();
		diceInstance.ToggleActionEnabled(value: true);
		diceInstance.UpdateDice(dice);
		diceInstance.UpdateDiceFace(updateOutline: false);
	}

	public void Boosted(bool boost)
	{
		boosted = boost;
		if (!boost)
		{
			if (BoostDiceSpawned)
			{
				BoostDiceSpawned = false;
				boostDiceInstance.StoreDiceInstance();
				boostDiceInstance = null;
				basicDiceInstance.SetNewPosition(oneDiceSpawnPosition);
			}
		}
		else
		{
			boostDice = defaultDice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
		}
	}

	public void ToggleActionValueModifier(ActionValueModifier actionValueModifier)
	{
		ActionValueModifier actionValueModifier2 = GetActionValueModifier(actionValueModifier.BattleActionInteractionEnum);
		if (actionValueModifier2 == null)
		{
			actionValueModifiers.Add(actionValueModifier);
		}
		else
		{
			actionValueModifier2.ActionValueModifierAmount = actionValueModifier.ActionValueModifierAmount;
		}
		defaultDice.ToggleActionValueModifier(actionValueModifiers);
		basicDice.ToggleActionValueModifier(actionValueModifiers);
		if (BasicDiceSpawned)
		{
			basicDiceInstance.UpdateDiceFace();
		}
		if (boosted)
		{
			boostDice.ToggleActionValueModifier(actionValueModifiers);
			if (BoostDiceSpawned)
			{
				boostDiceInstance.UpdateDiceFace();
			}
		}
	}

	private ActionValueModifier GetActionValueModifier(BattleActionInteractionEnum battleActionInteractionEnum)
	{
		for (int i = 0; i < actionValueModifiers.Count; i++)
		{
			if (actionValueModifiers[i].BattleActionInteractionEnum == battleActionInteractionEnum)
			{
				return actionValueModifiers[i];
			}
		}
		return null;
	}

	public void TurnPurifiesIntoNewAction(OptimizeEffect optimizeEffect)
	{
		basicDice = optimizeEffect.TurnPurifiesIntoNewAction(basicDice);
		boostDice = optimizeEffect.TurnPurifiesIntoNewAction(boostDice);
		UpdateActionValueModifier();
	}

	public List<DiceInstance> TransfigureDiceFace(BattleAction battleAction, int actionValue)
	{
		List<DiceInstance> list = new List<DiceInstance>();
		list.Add(basicDiceInstance);
		basicDiceInstance.ActionFace.BattleAction = battleAction;
		basicDiceInstance.ActionFace.NewBattleAction = battleAction;
		basicDiceInstance.ActionFace.ActionValue = actionValue;
		basicDiceInstance.ActionFace.NewActionValue = actionValue;
		basicDiceInstance.ActionFace.EnableSecondAction = false;
		basicDiceInstance.ActionFace.KeepChangesForBattle = true;
		basicDiceInstance.UpdateDiceFace();
		if (boosted)
		{
			list.Add(boostDiceInstance);
			boostDiceInstance.ActionFace.BattleAction = battleAction;
			boostDiceInstance.ActionFace.NewBattleAction = battleAction;
			boostDiceInstance.ActionFace.ActionValue = actionValue;
			boostDiceInstance.ActionFace.NewActionValue = actionValue;
			boostDiceInstance.ActionFace.EnableSecondAction = false;
			boostDiceInstance.ActionFace.KeepChangesForBattle = true;
			boostDiceInstance.UpdateDiceFace();
		}
		UpdateActionValueModifier();
		return list;
	}

	protected void ResetDice(ref Dice dice, DiceInstance diceInstance)
	{
		bool flag = false;
		if (!(defaultDice.GetDiceFaces().First().BattleAction is ChaoticAction) && !(defaultDice.GetDiceFaces().First().BattleAction is RecycleAction))
		{
			for (int i = 0; i < dice.GetDiceFaces().Length; i++)
			{
				if (dice.GetDiceFaces()[i].KeepChangesForBattle)
				{
					flag = true;
				}
			}
		}
		if (flag)
		{
			Dice dice2 = defaultDice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
			for (int j = 0; j < dice.GetDiceFaces().Length; j++)
			{
				DiceFace diceFace = dice.GetDiceFaces()[j];
				if (diceFace.KeepChangesForBattle)
				{
					dice2.GetDiceFaces()[j] = new DiceFace(diceFace.FaceName, diceFace.NewActionValue, diceFace.NewBattleAction);
					dice2.GetDiceFaces()[j].NewActionValue = diceFace.NewActionValue;
					dice2.GetDiceFaces()[j].NewBattleAction = diceFace.NewBattleAction;
					dice2.GetDiceFaces()[j].KeepChangesForBattle = true;
				}
			}
			dice = dice2;
		}
		else
		{
			dice = defaultDice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
		}
		UpdateActionValueModifier();
		diceInstance.UpdateDice(dice);
		diceInstance.UpdateDiceFace(updateOutline: false);
	}

	public void UpdateActionValueModifier()
	{
		for (int i = 0; i < actionValueModifiers.Count; i++)
		{
			ToggleActionValueModifier(actionValueModifiers[i]);
		}
	}

	public void StoreDice()
	{
		if (BasicDiceSpawned)
		{
			basicDiceInstance.StoreDiceInstance();
			basicDiceInstance = null;
			BasicDiceSpawned = false;
			StoreBoostDice();
		}
	}

	private void StoreBoostDice()
	{
		if (boosted && BoostDiceSpawned)
		{
			boostDiceInstance.StoreDiceInstance();
			boostDiceInstance = null;
			BoostDiceSpawned = false;
		}
	}

	public IEnumerator ActivationAnimation(Action activateDiceAction)
	{
		if (idlePosition == Vector3.one * 100000f)
		{
			idlePosition = skeletonTransform.position;
		}
		if (skeletonTransform.position != idlePosition)
		{
			skeletonTransform.position = idlePosition;
		}
		Vector3 startingPosition = skeletonTransform.position;
		Vector3 finalPosition = skeletonTransform.position + Vector3.right * attackingAnimationMovementAmount;
		yield return StartCoroutine(CoroutineUtility.CurveRoutine(attackAnimationDuration, attackAnimationCurve, delegate(float t, float v)
		{
			skeletonTransform.position = Vector3.Lerp(startingPosition, finalPosition, v);
		}));
		activateDiceAction?.Invoke();
	}
}
